//! 🎮️ An erased child command retains the actual typed Store VCS owner and initiating receiving continuation.
use super::*;
use semio_framework_os_store_engine_command::{ArtifactStoreNativeVcsTurn as _,ArtifactNativeVcsCommand,ArtifactNativeVcsRequest,ArtifactNativeVcsAdvance,ArtifactNativeVcsResult,ArtifactNativeVcsPhase};
use semio_framework_job::{StepContext,OriginalSourceBinding,OriginalTurnFailure,OriginalConstructionDemand,admit_original_construction,close_original_retained_step};
use semio_framework_value::{RetirementDemand,ValueRefusalKind,retained_clone::RetainedCloneClose};
use std::{any::Any,mem::{ManuallyDrop,size_of}};
/// 🧬️ Erasure retains the original concrete command and exposes only its fixed phase and physical terminal witness.
pub trait MemberNativeVcsCommand:Send{
 fn as_any_mut(&mut self)->&mut dyn Any;
 fn as_any(&self)->&dyn Any;
 fn phase(&self)->ArtifactNativeVcsPhase;
 fn next_construction_demands(&self)->Option<RetirementDemand>;
 fn terminal_is_empty(&self)->bool;
 fn release_demands(&self)->RetirementDemand;
}
struct Typed<P,M:Mutation<P>+Send+'static>{binding:OriginalSourceBinding,decoder:(u64,u64),identity:usize,body:usize,request:ManuallyDrop<Option<ArtifactNativeVcsRequest>>,command:ManuallyDrop<Option<ArtifactNativeVcsCommand<P,M>>>,retirement:RetainedCloneClose}
fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original member VCS owner, Store or decoder continuation changed")}
fn header<T>()->RetirementDemand{RetirementDemand{copy_bytes:size_of::<T>(),depth:1,..Default::default()}}
fn demand(d:RetirementDemand)->OriginalConstructionDemand{OriginalConstructionDemand{items:1,copy_bytes:d.copy_bytes,capacity_bytes:d.capacity_bytes,release_bytes:d.release_bytes,depth:d.depth}}
fn paid(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
impl<P:Send+Sync+'static,M:Mutation<P>+Send+'static> MemberNativeVcsCommand for Typed<P,M>{fn as_any_mut(&mut self)->&mut dyn Any{self}fn as_any(&self)->&dyn Any{self}fn phase(&self)->ArtifactNativeVcsPhase{self.command.as_ref().map_or(if self.request.is_some(){ArtifactNativeVcsPhase::Selecting}else{ArtifactNativeVcsPhase::Complete},|command|command.phase())}fn next_construction_demands(&self)->Option<RetirementDemand>{self.command.as_ref().map_or_else(||self.request.as_ref().map(|_|ArtifactNativeVcsCommand::<P,M>::capture_demands()),|command|command.next_construction_demands())}fn terminal_is_empty(&self)->bool{self.request.is_none()&&self.command.is_none()&&self.retirement.is_empty()}fn release_demands(&self)->RetirementDemand{RetirementDemand{release_bytes:size_of::<Self>(),depth:1,..Default::default()}}}
impl<P,M:Mutation<P>+Send+'static> Drop for Typed<P,M>{fn drop(&mut self){assert!(std::thread::panicking()||self.request.is_none()&&self.command.is_none()&&self.retirement.is_empty(),"member VCS command requires original funded closure")}}
impl<P,M> Typed<P,M>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{
 fn capture_demands()->RetirementDemand{RetirementDemand{capacity_bytes:size_of::<Self>(),..header::<(Self,Option<ArtifactNativeVcsRequest>,Option<ArtifactNativeVcsRequest>)>()}}
 fn validate(&self,store:&ArtifactStore<P,M>,cx:&StepContext<'_>)->Result<(),OriginalTurnFailure>{if !self.binding.matches(cx)||cx.native_receiving_identity()!=Some(self.decoder)||self.identity!=store.parts_ref().owners.snapshot_read_leases.identity(){return Err(invalid().into())}Ok(())}
 fn close_demands(&self,store:&ArtifactStore<P,M>,body:usize)->Result<RetirementDemand,ValueError>{if let Some(command)=self.command.as_ref(){if !command.terminal_is_empty(){return store.native_vcs_command_close_demands(command,body)}return Ok(header::<Option<ArtifactNativeVcsCommand<P,M>>>())}self.retirement.next_owner_demands::<ArtifactNativeVcsRequest>(self.request.is_some(),&None,self.body)}
}
pub(super)fn capture_demands<P,M>()->RetirementDemand where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{Typed::<P,M>::capture_demands()}
pub(super)fn admit<P,M>(store:&ArtifactStore<P,M>,request:&mut Option<ArtifactNativeVcsRequest>,cx:&mut StepContext<'_>,output:&mut Option<Box<dyn MemberNativeVcsCommand>>)->Result<bool,OriginalTurnFailure>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{if request.is_none(){return Err(invalid().into())}let binding=OriginalSourceBinding::borrow(cx);let identity=store.parts_ref().owners.snapshot_read_leases.identity();let body=cx.retained_grant().maximum_copy_bytes;let d=Typed::<P,M>::capture_demands();admit_original_construction(cx,output,demand(d),|control|Ok((Box::new(Typed::<P,M>{binding,identity,body,decoder:(control.ledger_identity(),control.retirement_recipient_identity().ok_or_else(invalid)?),request:ManuallyDrop::new(request.take()),command:ManuallyDrop::new(None),retirement:Default::default()})as Box<dyn MemberNativeVcsCommand>,paid(d))))}
fn typed<P:'static,M:Mutation<P>+Send+'static>(owner:&mut dyn MemberNativeVcsCommand)->Result<&mut Typed<P,M>,ValueError>{owner.as_any_mut().downcast_mut().ok_or_else(invalid)}
pub(super)fn advance<P,M>(store:&mut ArtifactStore<P,M>,owner:&mut dyn MemberNativeVcsCommand,cx:&mut StepContext<'_>)->Result<ArtifactNativeVcsAdvance,OriginalTurnFailure>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{let owner=typed::<P,M>(owner)?;owner.validate(store,cx)?;if owner.command.is_none(){let before=cx.retained_progress();store.admit_native_vcs_command(&mut owner.request,cx,&mut owner.command)?;let after=cx.retained_progress();let subtract=|a:usize,b:usize|a.checked_sub(b).ok_or_else(invalid);return Ok(ArtifactNativeVcsAdvance{phase:owner.phase(),progress:RetainedCloneProgress{copied_items:subtract(after.copied_items,before.copied_items)?,copied_bytes:subtract(after.copied_bytes,before.copied_bytes)?,retained_capacity_bytes:subtract(after.retained_capacity_bytes,before.retained_capacity_bytes)?,released_bytes:subtract(after.released_bytes,before.released_bytes)?}})}store.advance_native_vcs_command(owner.command.as_mut().unwrap(),cx)}
pub(super)fn take<P,M>(store:&ArtifactStore<P,M>,owner:&mut dyn MemberNativeVcsCommand,cx:&mut StepContext<'_>,output:&mut Option<ArtifactNativeVcsResult>)->Result<bool,OriginalTurnFailure>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{let owner=typed::<P,M>(owner)?;owner.validate(store,cx)?;store.take_native_vcs_result(owner.command.as_mut().ok_or_else(invalid)?,cx,output)}
pub(super)fn acknowledge<P,M>(store:&ArtifactStore<P,M>,owner:&mut dyn MemberNativeVcsCommand,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{let owner=typed::<P,M>(owner)?;owner.validate(store,cx)?;store.ack_native_vcs_command(owner.command.as_mut().ok_or_else(invalid)?,cx)}
pub(super)fn close_demands<P,M>(store:&ArtifactStore<P,M>,owner:&dyn MemberNativeVcsCommand,body:usize)->Result<RetirementDemand,ValueError>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{owner.as_any().downcast_ref::<Typed<P,M>>().ok_or_else(invalid)?.close_demands(store,body)}
pub(super)fn close<P,M>(store:&mut ArtifactStore<P,M>,owner:&mut dyn MemberNativeVcsCommand,cx:&mut StepContext<'_>)->Result<bool,OriginalTurnFailure>where P: semio_framework_os_spr::StoreState,M: semio_framework_os_spr::StoreMutationFor<P>{let owner=typed::<P,M>(owner)?;owner.validate(store,cx)?;if let Some(command)=owner.command.as_mut(){if !command.terminal_is_empty(){return store.close_native_vcs_command(command,cx).map(|_|false)}let d=header::<Option<ArtifactNativeVcsCommand<P,M>>>();close_original_retained_step(cx,d,|_|{owner.command.take();Ok(RetainedCloneStep::Progress(paid(d)))})?;return Ok(owner.terminal_is_empty())}let d=owner.close_demands(store,owner.body)?;close_original_retained_step(cx,d,|g|if owner.retirement.is_empty(){Ok(owner.retirement.begin_granted(&mut owner.request,g)?.unwrap_or(RetainedCloneStep::Complete(Default::default())))}else{owner.retirement.select(owner.body)?.step(g)})?;Ok(owner.terminal_is_empty())}
